    cal_path = pathlib.Path(__file__).resolve().parent.parent / 'calendars' / 'company_2025.ics'
    if not cal_path.is_file():
        return False
    target = datetime.datetime.strptime(date, '%Y-%m-%d').date()
    try:
        with cal_path.open('r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if line.startswith('DTSTART'):
                    # line may be like DTSTART:20250704 or DTSTART;VALUE=DATE:20250704
                    parts = line.split(':', 1)
                    if len(parts) != 2:
                        continue
                    dt_str = parts[1]
                    # handle date-only or datetime
                    if len(dt_str) >= 8:
                        try:
                            d = datetime.datetime.strptime(dt_str[:8], '%Y%m%d').date()
                        except ValueError:
                            continue
                        if d == target:
                            return True
    except Exception:
        return False
    return False

