import datetime, pathlib, re

HOLIDAYS = None

def _load_holidays():
    global HOLIDAYS
    if HOLIDAYS is not None:
        return
    HOLIDAYS = set()
    path = pathlib.Path('calendars/company_2025.ics')
    if not path.exists():
        return
    with path.open() as f:
        data = f.read()
    # Simple extraction of DTSTART dates in format YYYYMMDD
    for match in re.findall(r'DTSTART(?:;[^:]+)?:([0-9]{8})', data):
        try:
            dt = datetime.datetime.strptime(match, '%Y%m%d').date()
            HOLIDAYS.add(dt)
        except ValueError:
            pass


def is_holiday(date: str) -> bool:
    """True if date is a company holiday per calendars/company_2025.ics."""
    _load_holidays()
    try:
        d = datetime.datetime.strptime(date, '%Y-%m-%d').date()
    except ValueError:
        return False
    return d in HOLIDAYS

